#include <iostream>
using namespace std;

class FishBag {
    int count;
public:
    FishBag(int c) : count(c) {}
    int howMany() const { return count; }
};

FishBag operator+(const FishBag& a, const FishBag& b) {
    return FishBag(a.howMany() + b.howMany());
}

int main() {
    FishBag a(3);
    FishBag b(5);
    cout << (a + b).howMany() << endl;
    return 0;
}
